import subprocess
import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError("Commands file not found")
    if not os.path.exists(output_dir_path):
        os.makedirs(output_dir_path)
    output_files = []
    with open(commands_file_path, 'r') as file:
        reader = csv.reader(file)
        for index, row in enumerate(reader, start=1):
            command = row[0]
            output_file = os.path.join(output_dir_path, f'command_{index}_output.txt')
            try:
                result = subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                with open(output_file, 'w') as f:
                    if result.returncode == 0:
                        f.write(result.stdout.decode('utf-8'))
                    else:
                        f.write(f"Error: {result.stderr.decode('utf-8')}\nExit Code: {result.returncode}")
            except Exception as e:
                with open(output_file, 'w') as f:
                    f.write(f"Exception occurred: {str(e)}")
            output_files.append(output_file)
    return output_files

