import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("Invalid script path type")
    if not os.path.exists(script_path):
        raise OSError("Script path does not exist")
    process = subprocess.Popen([script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    cpu_usage = 0
    memory_usage = 0
    start_time = time.time()
    try:
        while process.poll() is None:
            if time.time() - start_time > timeout:
                process.terminate()
                break
            ps_process = psutil.Process(process.pid)
            cpu_usage += ps_process.cpu_percent(interval=0.1)
            memory_usage += ps_process.memory_info().rss
            time.sleep(0.1)
    except psutil.NoSuchProcess:
        pass
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

